public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list with only that element
    if (nums.length == 1) {
        List<Integer> permutation = new ArrayList<>();
        for (int num : nums) {
            permutation.add(num);
        }
        permutations.add(permutation);
        return permutations;
    }

    // Recursive case: for each position in the input array,
    // try swapping it with each other element
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        for (int j = 0; j < nums.length; j++) {
            int temp = nums[j];
            nums[j] = num;
            List<List<Integer>> subPermutations = permute(nums);
            for (List<Integer> subPermutation : subPermutations) {
                permutations.add(Arrays.asList(num, subPermutation.toArray(new Integer[0])));
            }
            nums[j] = temp;
        }
    }

    return permutations;
}

