private static String invertString(String string) {
    // Create a new string builder with the same length as the input string
    StringBuilder builder = new StringBuilder(string.length());

    // Build the inverted string by reversing the characters in the input string
    for (int i = string.length() - 1; i >= 0; i--) {
        builder.append(string.charAt(i));
    }

    // Return the inverted string
    return builder.toString();
}

