public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check if start and end are valid coordinates
    if (start.length != 2 || end.length != 2 || start[0] >= n || start[1] >= n || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // create a set to keep track of visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // create a queue to store the n-tersections to be visited
    Queue<Integer> toVisit = new LinkedList<>();

    // initialize the queue with the starting n-tersection
    toVisit.add(start[0] * n + start[1]);

    // loop until the queue is empty
    while (!toVisit.isEmpty()) {
        // get the current n-tersection
        int curr = toVisit.remove();

        // check if we have reached the ending n-tersection
        if (curr == end[0] * n + end[1]) {
            return "can be travelled";
        }

        // mark the current n-tersection as visited
        visited.add(curr);

        // get the n-tersections adjacent to the current n-tersection
        int[] adj = paths[curr];

        // add the adjacent n-tersections to the queue if they have not been visited yet
        for (int i = 0; i < adj.length; i++) {
            if (!visited.contains(adj[i])) {
                toVisit.add(adj[i]);
            }
        }
    }

    // if we reach this point, we have not found the ending n-tersection, so return "cannot be travelled"
    return "cannot be travelled";
}

