    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (Arrays.equals(current, end)) {
            // If it is, we can return "can be travelled"
            return "can be travelled";
        }

        // Get the neighbors of the current n-tersection
        int[][] neighbors = getNeighbors(current, paths);

        // Loop through the neighbors
        for (int[] neighbor : neighbors) {
            // Check if the current n-tersection has not been visited
            if (!visited.contains(neighbor)) {
                // If not, mark it as visited and add it to the queue
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    // If the queue is empty, we can return "cannot be travelled"
    return "cannot be travelled";
}

private static int[][] getNeighbors(int[] current, int[][] paths) {
    // Initialize an empty array list to store the neighbors
    ArrayList<int[]> neighbors = new ArrayList<>();

    // Loop through the paths
    for (int[] path : paths) {
        // Check if the current n-tersection is contained in the path
        if (Arrays.asList(path).contains(current)) {
            // If it is, add the path to the neighbors array list
            neighbors.add(path);
        }
    }

    // Convert the array list to an int[][] array
    return neighbors.toArray(new int[neighbors.size()][]);
}

