public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n < 1) {
        return "cannot be travelled";
    }

    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Mark the starting n-tersection as visited
    visited[start[0] - 1] = true;

    // Use a queue to maintain a list of n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] currentNtersection = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(currentNtersection, end)) {
            return "can be travelled";
        }

        // Add all unvisited n-tersections to the queue
        for (int[] path : paths) {
            int adjacentNtersectionX = path[0] - 1;
            int adjacentNtersectionY = path[1] - 1;
            if (!visited[adjacentNtersectionX] && !visited[adjacentNtersectionY]) {
                queue.add(path);
                visited[adjacentNtersectionX] = true;
                visited[adjacentNtersectionY] = true;
            }
        }
    }

    // If the algorithm reaches this point, it means that there is no path from the starting n-tersection to the ending n-tersection
    return "cannot be travelled";
}

