private int findPivot(int[] nums, int start, int end) {
    if (start > end) {
        return -1;
    }

    int mid = (start + end) / 2;
    if (nums[mid] > nums[start]) {
        return mid;
    } else if (nums[mid] < nums[end]) {
        return findPivot(nums, mid + 1, end);
    }

    // handle duplicates
    for (int i = mid - 1; i >= 0; i--) {
        if (nums[i] > nums[mid]) {
            return i;
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the indices of the 5% smallest and largest elements
    int smallestIndex = (int) (arr.length * 0.05);
    int largestIndex = arr.length - smallestIndex;

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = smallestIndex; i < largestIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = sum / (arr.length - 2 * smallestIndex);

    // Round the mean to 5 decimal places
    return Math.round(mean * 100000d) / 100000d;
}

