    int smallest5Percent = (int) (arr.length * 0.05);
    int[] smallest5PercentElements = new int[smallest5Percent];
    for (int i = 0; i < smallest5Percent; i++) {
        smallest5PercentElements[i] = arr[i];
    }

    // Calculate the largest 5% of elements
    int largest5Percent = (int) (arr.length * 0.05);
    int[] largest5PercentElements = new int[largest5Percent];
    for (int i = arr.length - 1; i >= arr.length - largest5Percent; i--) {
        largest5PercentElements[largest5Percent - 1 - i] = arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = 0;
    for (int i = smallest5Percent; i < arr.length - largest5Percent; i++) {
        mean += arr[i];
    }
    mean /= (arr.length - smallest5Percent - largest5Percent);

    // Return the mean with an error threshold of 10^-5
    if (Math.abs(mean - (double) arr.length / 2) > 0.00001) {
        throw new IllegalArgumentException("The mean calculated is not within the error threshold of 10^-5");
    }
    return mean;
}

