public static Boolean canArrange(int[] arr, int k) {
    // Check if the divisor is a divisor of the sum of the array
    if (arr.length % 2 == 1 || k % arr.length != 0) {
      return false;
    }

    // Create a map to store the pairs and their sum
    Map<Integer, Integer> pairs = new HashMap<>();

    // Iterate over the array and create pairs
    for (int i = 0; i < arr.length / 2; i++) {
      int pairSum = arr[i * 2] + arr[i * 2 + 1];
      if (pairSum % k != 0) {
        return false;
      }
      pairs.put(pairSum, pairs.getOrDefault(pairSum, 0) + 1);
    }

    // Check if the number of pairs is equal to the number of divisors of k
    return pairs.size() == k / arr.length;
  }

