      visited[node] = true;
      for (int neighbor : edges[node]) {
        if (!visited[neighbor]) {
          queue.offer(neighbor);
        }
      }
    }

    // If the node has an apple and it is not the starting node, add its time to the minimum time
    if (hasApple[node] && node != 0) {
      minTime += node;
    }
  }

  // Return the minimum time
  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the distance between each node and the starting node (node 0)
    int[][] dist = new int[n][n];
    for (int i = 0; i < n; i++) {
        dist[i][0] = Integer.MAX_VALUE;
    }

    // Breadth-first search to find the minimum distance from node 0 to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    dist[0][0] = 0;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : edges[node]) {
            if (dist[neighbor][0] == Integer.MAX_VALUE) {
                dist[neighbor][0] = dist[node][0] + 1;
                queue.offer(neighbor);
            }
        }
    }

    // Find the maximum distance among all nodes
    int maxDist = 0;
    for (int i = 0; i < n; i++) {
        if (dist[i][0] > maxDist) {
            maxDist = dist[i][0];
        }
    }

    // If a node does not have an apple, the distance from node 0 to that node is the maximum distance, so return 0
    for (int i = 0; i < n; i++) {
        if (!hasApple[i] && dist[i][0] == maxDist) {
            return 0;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return maxDist;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the distance array with the maximum value
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);

    // Set the distance of node 0 to 0
    dist[0] = 0;

    // Priority queue to store the nodes to visit
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    pq.offer(0);

    // Loop until the priority queue is empty
    while (!pq.isEmpty()) {
        // Get the node with the minimum distance
        int node = pq.poll();

        // If the node has an apple, return the distance
        if (hasApple[node]) {
            return dist[node];
        }

        // Loop through the neighbors of the node
        for (int i = 0; i < edges[node].length; i++) {
            int neighbor = edges[node][i];
            // If the neighbor has not been visited, mark it as visited and enqueue it
            if (dist[neighbor] == Integer.MAX_VALUE) {
                dist[neighbor] = dist[node] + 1;
                pq.offer(neighbor);
            }
        }
    }

    // If no path to collect all apples is found, return -1
    return -1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Use BFS to collect all apples and calculate the minimum time required
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int time = 0;
    queue.offer(0);
    visited[0] = true;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int node = queue.poll();
            if (hasApple[node]) {
                // Apple found! Add it to the list and mark it as visited
                queue.offer(node);
                visited[node] = true;
            }
            // Add all neighbors of the current node to the queue
            for (int neighbor : graph.getNeighbors(node)) {
                if (!visited[neighbor]) {
                    queue.offer(neighbor);
                    visited[neighbor] = true;
                }
            }
        }
        time++;
    }

    // Return the minimum time required
    return time;
}

