public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 1) {
        return 0;
    }
    if (hasApple[0]) {
        return 1;
    }
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[0] = 0;
    for (int[] edge : edges) {
        int src = edge[0];
        int dst = edge[1];
        if (hasApple[src] && dist[src] != -1) {
            dist[dst] = Math.min(dist[dst], dist[src] + 1);
        }
        if (hasApple[dst] && dist[dst] != -1) {
            dist[src] = Math.min(dist[src], dist[dst] + 1);
        }
    }
    int minTime = Integer.MAX_VALUE;
    for (int i = 1; i < n; i++) {
        if (hasApple[i] && dist[i] != -1) {
            minTime = Math.min(minTime, dist[i]);
        }
    }
    return minTime == Integer.MAX_VALUE ? 0 : minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    boolean[] used = new boolean[s.length()];

    // step 1
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (!used[i]) {
            result.append(c);
            used[i] = true;
        }
    }

    // step 2
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (used[i]) continue;
        int j = i;
        while (j < s.length() && s.charAt(j) > c) {
            j++;
        }
        if (j < s.length()) {
            result.append(s.charAt(j));
            used[j] = true;
        }
    }

    // step 3
    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (used[i]) continue;
        int j = i;
        while (j >= 0 && s.charAt(j) < c) {
            j--;
        }
        if (j >= 0) {
            result.insert(0, s.charAt(j));
            used[j] = true;
        }
    }

    return result.toString();
}

