  }
  return largestChar;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int average = sum / nums.length;

    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }

    int rightSum = sum - leftSum;

    return leftSum == average && rightSum == average;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the array
    int average = Arrays.stream(nums).sum() / nums.length;

    // Check if it is possible to split the array into two parts with the same average
    for (int i = 0; i < nums.length - 1; i++) {
        // Calculate the sum of the two parts
        int sum1 = Arrays.stream(nums, 0, i).sum() + Arrays.stream(nums, i + 1, nums.length).sum();
        if (sum1 == 2 * average) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the input array
    double average = calculateAverage(nums);

    // Check if the average is even
    if (average % 2 == 0) {
        // Split the input array into two arrays
        int[] left = Arrays.copyOfRange(nums, 0, nums.length / 2);
        int[] right = Arrays.copyOfRange(nums, nums.length / 2, nums.length);

        // Calculate the average of the left and right arrays
        double leftAverage = calculateAverage(left);
        double rightAverage = calculateAverage(right);

        // Check if the averages are equal
        if (leftAverage == rightAverage) {
            return true;
        }
    }

    return false;
}

