    double average = (double) sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false;
    }

    // Convert the average to an integer
    int targetAverage = (int) average;

    // Initialize the two arrays
    int[] arr1 = new int[nums.length / 2];
    int[] arr2 = new int[nums.length - arr1.length];

    // Iterate over the input array and assign elements to the two arrays
    int i = 0;
    for (int num : nums) {
        if (i < arr1.length) {
            arr1[i] = num;
        } else {
            arr2[i - arr1.length] = num;
        }

        i++;
    }

