public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 2] + cost[i], dp[i - 1] + cost[i]);
    }
    return Math.min(dp[cost.length - 2], dp[cost.length - 1]);
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = 0;

  // Check if the input array has at least 2 elements
  if (cost == null || cost.length < 2)
    throw new IllegalArgumentException("Invalid input array");

  // Initialize the min cost and the current cost
  int currCost = cost[0], minCurrCost = currCost;

  // Iterate through the rest of the elements
  for (int i = 1; i < cost.length; i++) {
    // Update the current cost
    currCost = Math.min(currCost, minCurrCost) + cost[i];

    // Update the minimum current cost
    minCurrCost = Math.min(minCurrCost, currCost);
  }

  return minCurrCost;
}

