return minCost;
}

int cost1 = currentIndex == 0 ? 0 : minCostClimbingStairs(cost, currentIndex - 1, minCost);
int cost2 = currentIndex == 1 ? 0 : minCostClimbingStairs(cost, currentIndex - 2, minCost);

return Math.min(cost1 + cost[currentIndex], cost2 + cost[currentIndex - 1]);
}

