public int minCostClimbingStairs(int[] cost) {
  if (cost == null || cost.length == 0) {
    throw new IllegalArgumentException("Invalid input: cost array cannot be null or empty");
  }

  int minCost = Integer.MAX_VALUE;
  for (int i = 0; i < cost.length; i++) {
    int stepCost = cost[i];
    int nextStepIndex = i + 1;
    if (nextStepIndex < cost.length) {
      int nextStepCost = minCostClimbingStairs(nextStepIndex, cost);
      if (nextStepCost != Integer.MAX_VALUE) {
        int costToClimbStairs = stepCost + nextStepCost;
        minCost = Math.min(minCost, costToClimbStairs);
      }
    }
  }

  return minCost;
}

public int minCostClimbingStairs(int startIndex, int[] cost) {
  if (startIndex < 0 || startIndex >= cost.length) {
    throw new IllegalArgumentException("Invalid input: startIndex must be between 0 and cost.length");
  }

  if (cost[startIndex] == 1) {
    return 1;
  }

  int minCost = Integer.MAX_VALUE;
  for (int i = startIndex + 1; i < cost.length; i++) {
    int stepCost = cost[i];
    int nextStepIndex = i + 1;
    if (nextStepIndex < cost.length) {
      int nextStepCost = minCostClimbingStairs(nextStepIndex, cost);
      if (nextStepCost != Integer.MAX_VALUE) {
        int costToClimbStairs = stepCost + nextStepCost;
        minCost = Math.min(minCost, costToClimbStairs);
      }
    }
  }

  return minCost;
}

