public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOps = 0;
  while (!isEqual(arr)) {
    int x = minIndex(arr);
    int y = maxIndex(arr);
    arr[x] -= 1;
    arr[y] += 1;
    minOps++;
  }

  return minOps;
}

private boolean isEqual(int[] arr) {
  for (int i = 0; i < arr.length - 1; i++) {
    if (arr[i] != arr[i + 1]) {
      return false;
    }
  }
  return true;
}

private int minIndex(int[] arr) {
  int min = Integer.MAX_VALUE;
  int minIndex = -1;
  for (int i = 0; i < arr.length; i++) {
    if (arr[i] < min) {
      min = arr[i];
      minIndex = i;
    }
  }
  return minIndex;
}

private int maxIndex(int[] arr) {
  int max = Integer.MIN_VALUE;
  int maxIndex = -1;
  for (int i = 0; i < arr.length; i++) {
    if (arr[i] > max) {
      max = arr[i];
      maxIndex = i;
    }
  }
  return maxIndex;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOps = 0;
    int x = 0, y = 0;
    while (arr[x] != arr[y]) {
        minOps++;
        arr[x] -= 1;
        arr[y] += 1;
        x = (x + 1) % n;
        y = (y + 1) % n;
    }

    return minOps;
}

public int minOperations(int n) {
    if (n == 1) {
        return 0;
    }
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!isArrEqual(arr)) {
        int[] minOperationsByIndex = new int[n];
        for (int i = 0; i < n; i++) {
            int x = 2 * i;
            int y = (i + 1) % n;
            minOperationsByIndex[i] = Math.min(Math.abs(arr[x] - arr[y]), minOperationsByIndex[i - 1]);
        }
        minOperations += minOperationsByIndex[n - 1];
        for (int i = 0; i < n; i++) {
            arr[i] -= minOperationsByIndex[i];
        }
    }
    return minOperations;
}

private boolean isArrEqual(int[] arr) {
    int min = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != min) {
            return false;
        }
    }
    return true;
}

