        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (arr[0] != arr[n - 1]) {
        int currentIncrease = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] != arr[0]) {
                currentIncrease++;
            }
        }
        minOperations += currentIncrease;

        int target = arr[0] + currentIncrease;
        for (int i = 0; i < n; i++) {
            if (arr[i] < target) {
                arr[i] = target;
            }
        }
    }

    return minOperations;
}

