public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence
    int f1 = 1, f2 = 1, fn = 0;

    // Loop until the sum of the Fibonacci sequence is greater than or equal to k
    while (f1 + f2 < k) {
        fn = f1 + f2;
        f1 = f2;
        f2 = fn;
    }

    // Count the number of Fibonacci numbers in the sequence
    int count = 0;
    while (fn > 0) {
        count++;
        fn = fn - f1;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Initialize two variables to keep track of the current sum and the previous Fibonacci number
    int currentSum = 0, previous = 0;
    int count = 0;

    // Iterate through the Fibonacci numbers until the current sum exceeds k
    while (currentSum < k) {
        // Add the current Fibonacci number to the sum
        currentSum += previous;

        // Increment the count
        count++;

        // Update the previous Fibonacci number
        previous = currentSum - previous;
    }

    // Return the count
    return count;
}

