    }

    // Check if the last digit is equal to 0 or 9
    if (digits[digits.length - 1] == 0 || digits[digits.length - 1] == 9) {
        return false;
    }

    // Check if the digits are one more or one less than the adjacent digits
    for (int i = 1; i < digits.length; i++) {
        if (Math.abs(digits[i] - digits[i - 1]) != 1) {
            return false;
        }
    }

    return true;
}

