        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int current = 1;
                while (i + current < m && j + current < n && mat[i + current][j + current] == 1) {
                    current++;
                }
                max = Math.max(max, current);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int current = 1;
                while (i - current >= 0 && j - current >= 0 && mat[i - current][j - current] == 1) {
                    current++;
                }
                max = Math.max(max, current);
            }
        }
    }

    return max;
}

public static int longestLine(int[][] mat) {
    // Define the maximum length of a line
    int maxLength = 0;

    // Iterate over each row of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Define the current row
        int[] row = mat[i];

        // Iterate over each element of the current row
        for (int j = 0; j < row.length; j++) {
            // If the element is 1, start counting the length of the line
            if (row[j] == 1) {
                int length = 1;

                // Check if the element is at the edge of the matrix
                if (i == 0 || j == 0 || i == mat.length - 1 || j == mat[0].length - 1) {
                    // If it is, the line is only 1 element long
                    length = 1;
                } else {
                    // Otherwise, check in all the surrounding elements
                    // are also 1s
                    boolean isLine = true;

                    // Check above
                    for (int k = i - 1; k >= 0; k--) {
                        if (mat[k][j] != 1) {
                            isLine = false;
                            break;
                        }
                    }

                    // Check below
                    for (int k = i + 1; k < mat.length; k++) {
                        if (mat[k][j] != 1) {
                            isLine = false;
                            break;
                        }
                    }

                    // Check left
                    for (int k = j - 1; k >= 0; k--) {
                        if (mat[i][k] != 1) {
                            isLine = false;
                            break;
                        }
                    }

                    // Check right
                    for (int k = j + 1; k < row.length; k++) {
                        if (mat[i][k] != 1) {
                            isLine = false;
                            break;
                        }
                    }

                    // If all surrounding elements are 1s, the line is valid
                    if (isLine) {
                        length++;
                    }
                }

                // Update the maximum length if necessary
                maxLength = Math.max(maxLength, length);
            }
        }
    }

    // Return the maximum length
    return maxLength;
}

