public static int squarePermutations(int[] A) {
    Set<Integer> permutations = new HashSet<>();
    permutations.add(0);
    for (int i = 0; i < A.length; i++) {
        int sum = 0;
        for (int j = i - 1; j < i + 2; j++) {
            if (j < 0 || j >= A.length) {
                continue;
            }
            sum += A[j];
        }
        if (sum * sum == A[i]) {
            permutations.add(i);
        }
    }
    return permutations.size();
}

