  // Store the sum of each pair of adjacent elements in the array
  int[] sums = new int[A.length - 1];
  for (int i = 0; i < sums.length; i++) {
    sums[i] = A[i] + A[i + 1];
  }

  // Count the number of perfect squares in the sums array
  int numSquares = 0;
  for (int sum : sums) {
    if (Math.sqrt(sum) == (int) Math.sqrt(sum)) {
      numSquares++;
    }
  }

  // Get the number of unique permutations of A
  int numPermutations = factorial(A.length);

  // Return the number of square permutations
  return numPermutations / (numSquares + 1);
}

private static int factorial(int n) {
  if (n == 0) {
    return 1;
  }
  return n * factorial(n - 1);
}

public static int squarePermutations(int[] A) {
    // Check if the input array is null or empty
    if (A == null || A.length == 0) {
        return 0;
    }

    // Check if all elements in the input array are non-negative
    for (int i = 0; i < A.length; i++) {
        if (A[i] < 0) {
            throw new IllegalArgumentException("All elements in the input array must be non-negative");
        }
    }

    // Sort the input array in ascending order
    Arrays.sort(A);

    // Initialize the number of permutations to 0
    int permutations = 0;

    // Iterate over the input array
    for (int i = 0; i < A.length; i++) {
        // Check if the sum of the current element and the next element is a perfect square
        if (i < A.length - 1 && Math.pow(A[i] + A[i + 1], 2) == Math.pow(A[i] * A[i + 1], 2)) {
            // Increment the number of permutations
            permutations++;
        }
    }

    // Return the number of square permutations
    return permutations;
}

public static int squarePermutations(int[] A) {
