    Arrays.sort(A);

    // Loop through the array and check for square pairs
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (sum % 2 == 0 && Math.sqrt(sum) == Math.floor(Math.sqrt(sum))) {
            result++;
        }
    }

    // If the last element is a square, add it to the result
    if (A[A.length - 1] % 2 == 0 && Math.sqrt(A[A.length - 1]) == Math.floor(Math.sqrt(A[A.length - 1]))) {
        result++;
    }

    return result;
}

