    Set<int[]> permutations = new HashSet<>();

    // Iterate over the elements of the input array
    for (int i = 0; i < A.length; i++) {
        // Check if the current element is a perfect square
        if (isPerfectSquare(A[i])) {
            // If it is a perfect square, add it to the set of permutations
            permutations.add(clone(A));
        }
    }

    // Return the size of the set of permutations
    return permutations.size();
