public static int largestRectangleArea(int[] heights) {
    // Initialize variables
    int maxArea = 0;
    int currentArea = 0;
    int i = 0;
    int j = 0;

    // Loop through the heights array from left to right
    while (i < heights.length) {
        // Find the first index where the height is 0
        while (i < heights.length && heights[i] == 0) {
            i++;
        }

        // If we reached the end of the array, return the max area
        if (i == heights.length) {
            return maxArea;
        }

        // Initialize the current area with the height of the first non-zero height bar
        currentArea = heights[i];
        j = i + 1;

        // Loop through the remaining heights from the current index
        while (j < heights.length) {
            // If the current height is greater than the current area, update the area
            if (heights[j] > currentArea) {
                currentArea = heights[j];
            }

            // If the current height is less than or equal to the current area,
            // we can calculate the area of the rectangle and update the max area
            if (heights[j] <= currentArea) {
                maxArea = Math.max(maxArea, currentArea * (j - i + 1));
                i = j + 1;
                break;
            }

            j++;
        }
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
