   for (int i = 1; i < n; i++) {
       left[i] = i;
       for (int j = 0; j < i; j++) {
           if (heights[j] <= heights[i]) {
               left[i] = Math.max(left[i], left[j] + 1);
           }
       }
   }

   right[n - 1] = n - 1;
   for (int i = n - 2; i >= 0; i--) {
       right[i] = i;
       for (int j = n - 1; j > i; j--) {
           if (heights[j] <= heights[i]) {
               right[i] = Math.min(right[i], right[j - 1] + 1);
           }
       }
   }

   int maxArea = 0;
   for (int i = 0; i < n; i++) {
       maxArea = Math.max(maxArea, (right[i] - left[i] + 1) * heights[i]);
   }

   return maxArea;
}

