public int findNthUglyNumber(int N) {
    if (N <= 0)
        throw new IllegalArgumentException("N must be a positive integer");

    int[] factors = new int[4]; // prime factors 2, 3, 5, and 7
    factors[0] = 1; // initialize the first ugly number

    for (int i = 1; i < N; i++) {
        factors[0]++; // increment the factor for the current ugly number

        // calculate the next ugly number by multiplying the current factors
        int product = 1;
        for (int j = 0; j < factors.length; j++) {
            product *= factors[j];
        }

        // add the next ugly number to the list
        factors[0] = product;
    }

    // return the nth ugly number
    return factors[0];
}

public static int findNthUglyNumber(int n) {
