        throw new IllegalArgumentException("n must be positive");
    }

    int[] factors = {2, 3, 5};
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int nextMultiplier = 0;
    int factorIndex = 0;
    for (int i = 1; i < n; i++) {
        int factor = factors[factorIndex];
        int next = factor * uglyNumbers[nextMultiplier];
        if (next < uglyNumbers[i - 1]) {
            factorIndex++;
            nextMultiplier = i - 1;
            factor = factors[factorIndex];
            next = factor * uglyNumbers[nextMultiplier];
        }
        uglyNumbers[i] = next;
        nextMultiplier++;
    }
    return uglyNumbers[n - 1];
}

