        int smallestFactor = Math.min(factor2, Math.min(factor3, factor5));

        // Add the smallest factor to the list
        uglyNumbers.add(smallestFactor);

        // Update the current number and its factors
        uglyNumber += smallestFactor;
        factor2 = uglyNumber * 2;
        factor3 = uglyNumber * 3;
        factor5 = uglyNumber * 5;
    }

