        int minUglyNumber = Math.min(uglyNumbers[nextUglyNumberIndex] * 2, Math.min(uglyNumbers[nextUglyNumberIndex] * 3, uglyNumbers[nextUglyNumberIndex] * 5));

        // Increment the index of the next ugly number to be processed
        nextUglyNumberIndex++;

        // Add the minimum ugly number to the array of ugly numbers
        uglyNumbers[nextUglyNumberIndex] = minUglyNumber;
    }

    // Return the last ugly number in the array
    return uglyNumbers[n - 1];
}

