public static List<Integer> lexicalOrder(int n) {
    // Create a String array to store the numbers in lexicographical order
    String[] strings = new String[n];
    for (int i = 1; i <= n; i++) {
        strings[i - 1] = Integer.toString(i);
    }
    // Sort the array in lexicographical order
    Arrays.sort(strings);
    // Convert the sorted array to a List of integers
    List<Integer> list = new ArrayList<>();
    for (String s : strings) {
        list.add(Integer.parseInt(s));
    }
    return list;
}

