}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Set<Integer> seen = new HashSet<>();
    for (int num : nums) {
        if (!seen.contains(num)) {
            sum += num;
            seen.add(num);
        }
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    // Initialize a hash set to store unique elements
    Set<Integer> uniqueSet = new HashSet<>();

    // Iterate over the input array and add unique elements to the hash set
    for (int num : nums) {
        if (!uniqueSet.contains(num)) {
            uniqueSet.add(num);
        }
    }

    // Iterate over the hash set and calculate the sum of its elements
    int sum = 0;
    for (int num : uniqueSet) {
        sum += num;
    }

    return sum;
}

