public static int minPerfectSquareSum(int n) {
  int count = 0;
  for (int i = 1; i <= n; i++) {
    int root = (int)Math.sqrt(i);
    if (root * root == i) {
      count++;
    }
  }
  return count;
}

public static int minPerfectSquareSum(int n) {
    // Initialize a set to store the perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Loop through the natural numbers and check if they are perfect squares
    for (int i = 1; i <= n; i++) {
        int squareRoot = (int) Math.sqrt(i);
        if (squareRoot * squareRoot == i) {
            perfectSquares.add(i);
        }
    }

    // Return the minimum number of perfect square numbers that sum up to n
    return perfectSquares.size();
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            count++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
      throw new IllegalArgumentException("n must be a positive integer");
    }

    int minSquares = 1;
    int currentSum = 1;

    for (int i = 2; i <= n; i++) {
      currentSum += i;
      int sqrt = (int) Math.sqrt(currentSum);
      if (sqrt * sqrt == currentSum) {
        minSquares++;
      }
    }

    return minSquares;
  }

