        if (root * root == i) {
            count++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    // Check if input string is empty
    if (s.isEmpty()) {
        return "";
    }

    // Split input string into an array of words
    String[] words = s.split(" ");

    // Initialize result string
    StringBuilder result = new StringBuilder();

    // Iterate through each word and reverse its characters
    for (int i = 0; i < words.length; i++) {
        // Reverse word characters
        String word = new StringBuilder(words[i]).reverse().toString();

        // Add word to result
        result.append(word);

        // Add space if not last word
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse().toString());
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String[] words = s.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }

    return String.join(" ", words);
}

public static String reverseWords(String s) {
    return Arrays.stream(s.split(" "))
                .map(word -> new StringBuilder(word).reverse().toString())
                .collect(Collectors.joining(" "));
}

